using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "TridentofDepthsOmenData", menuName = "Data/Battle/Omens System/Omen Data/Cellarius/TridentofDepthsOmenData")]
public class TridentofDepthsOmenData : OnNewRuneOmenData
{
	[Header("Trident of Depths")]
	[SerializeField]
	private int additionalWaveAmount;

	[SerializeField]
	private int fewerPurificationAmount;

	[NonSerialized]
	private Func<int, int> omenAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		base.Initialize(omenInstance);
		ReferenceSingleton<CellariusOmensHandler>.Instance.TridentOfDepthsWaveOmenAction = (int effectAmount) => effectAmount + additionalWaveAmount;
		omenAction = (int purifyAmount) => purifyAmount - fewerPurificationAmount;
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyFinalModifierOmenActions.Add(omenAction);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<CellariusOmensHandler>.Instance.TridentOfDepthsWaveOmenAction = null;
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnPlayerDealPurifyFinalModifierOmenActions.Remove(omenAction);
	}

	public override string OmenConvertedDescription()
	{
		return Smart.Format(GetOmenRawLocalizedDescription(), additionalWaveAmount) + "\n" + base.OmenConvertedDescription() + "\n" + Smart.Format(base.localizationManager.GetLocalizedString("YouDealLessPurification"), fewerPurificationAmount);
	}
}
